package com.example;
import static org.springframework.web.reactive.function.server.RequestPredicates.*;
import static org.springframework.web.reactive.function.server.RouterFunctions.*;
import org.springframework.context.annotation.Bean;
import org.springframework.http.MediaType;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.ServerResponse;
public class OwnerRoutes {
  @Bean
  RouterFunction<ServerResponse> ownerRoutes(OwnerHandler handler) {
    return route(GET("/owners/{id}").and(accept(MediaType.APPLICATION_JSON)), handler::show)
        .andRoute(POST("/owners"), handler::create)
        .andNest(path("/owners/{id}/pets"), route(GET(""), handler::pets));
  }
}

package com.example;
import static org.springframework.web.servlet.function.RequestPredicates.accept;
import org.springframework.context.annotation.Bean;
import org.springframework.http.MediaType;
import org.springframework.web.servlet.function.RouterFunction;
import org.springframework.web.servlet.function.RouterFunctions;
import org.springframework.web.servlet.function.ServerResponse;
public class ApiConfig {
  private final UserService users;
  ApiConfig(UserService users) { this.users = users; }
  @Bean
  public RouterFunction<ServerResponse> api() {
    return RouterFunctions.route()
        .path("/api", b -> b
            .GET("/users", this::listUsers)
            .POST("/users", accept(MediaType.APPLICATION_JSON), request -> users.create(request)))
        .filter((request, next) -> next.handle(request))
        .build();
  }
  ServerResponse listUsers(org.springframework.web.servlet.function.ServerRequest r) { return null; }
}

package com.example;
import org.springdoc.webflux.core.fn.SpringdocRouteBuilder;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.ServerResponse;
public class PostEndpoint implements CustomEndpoint {
  @Override
  public RouterFunction<ServerResponse> endpoint() {
    final var tag = "PostV1alpha1Console";
    return SpringdocRouteBuilder.route()
        .GET("posts", this::listPost, builder -> {
          builder.operationId("ListPosts").description("List posts.").tag(tag);
          PostQuery.buildParameters(builder);
        })
        .PUT("posts/{name}/publish", this::publishPost, builder -> builder.operationId("PublishPost").tag(tag))
        .build();
  }
}

package com.example;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.server.RequestPredicates;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.RouterFunctions;
import org.springframework.web.reactive.function.server.ServerResponse;
public class PetRoutes {
  static final String BASE = "/pets";
  @Bean
  RouterFunction<ServerResponse> pets() {
    return RouterFunctions.nest(RequestPredicates.path(BASE), petRoutes());
  }
  private RouterFunction<ServerResponse> petRoutes() {
    return RouterFunctions.route(RequestPredicates.method(HttpMethod.DELETE).and(RequestPredicates.path("/{id}")), this::remove);
  }
}

package com.example;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.RouterFunctions;
import org.springframework.web.reactive.function.server.ServerResponse;
public class Misc {
  @Bean
  RouterFunction<ServerResponse> misc(String base) {
    return RouterFunctions.route()
        .GET(base, this::a)
        .GET("/b", request -> ServerResponse.ok().bodyValue("b"))
        .build();
  }
  @Bean
  RouterFunction<ServerResponse> built(ApplicationContext context) {
    var builder = new CustomEndpointsBuilder();
    context.getBeansOfType(CustomEndpoint.class).values().forEach(builder::add);
    return builder.build();
  }
}

package com.example;
import org.springframework.context.annotation.Bean;
import org.springframework.core.io.ClassPathResource;
import org.springframework.web.reactive.function.server.RouterFunctions;
import org.springframework.web.reactive.function.server.ServerResponse;
public class Gateway {
  @Bean
  RouterFunction<?> routerFunction() {
    RouterFunction router = RouterFunctions.resources("/**", new ClassPathResource("static/"))
        .andRoute(RequestPredicates.GET("/"), request -> ServerResponse.ok().bodyValue(indexHtml));
    return router;
  }
  public java.util.List<RouterFunction<ServerResponse>> collected() {
    return java.util.List.of(RouterFunctions.route().GET("/list", this::a).build());
  }
  public Object notRoutes() {
    return RouterFunctions.route().GET("/never", this::a).build();
  }
}

package com.example;
import java.util.function.Supplier;
import org.springdoc.webflux.core.fn.SpringdocRouteBuilder;
import org.springframework.web.reactive.function.server.RequestPredicates;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.ServerResponse;
public class NotificationEndpoint implements CustomEndpoint {
  public RouterFunction<ServerResponse> endpoint() {
    return SpringdocRouteBuilder.route()
        .nest(RequestPredicates.path("/userspaces/{username}"), userspaceScopedApis())
        .build();
  }
  Supplier<RouterFunction<ServerResponse>> userspaceScopedApis() {
    return () -> SpringdocRouteBuilder.route()
        .GET("/notifications", this::listNotification, builder -> builder.operationId("ListUserNotifications"))
        .build();
  }
}

package com.example;
import org.springframework.context.annotation.Bean;
import org.springframework.web.reactive.function.server.RouterFunction;
import org.springframework.web.reactive.function.server.RouterFunctions;
import org.springframework.web.reactive.function.server.ServerResponse;
public class Later {
  boolean legacy;
  @Bean
  RouterFunction<ServerResponse> routes() {
    String prefix = "/v1";
    prefix = "/v2";
    var builder = RouterFunctions.route();
    var same = builder;
    same.path(prefix, b -> b.GET("/items", this::list));
    String other = "/a";
    if (legacy) { other = "/b"; }
    builder.GET(other, this::list);
    return builder.build();
  }
}
